# Reads version.txt (single source of truth) and writes src\AppVersion.cs.
# Versions must be MAJOR.MINOR.PATCH. The build fails on anything else.
param([string]$Root = (Split-Path -Parent $PSScriptRoot))

$versionFile = Join-Path $Root "version.txt"
$version = (Get-Content -LiteralPath $versionFile -Raw).Trim()
if ($version -notmatch '^\d+\.\d+\.\d+$') {
    Write-Error "version.txt must contain MAJOR.MINOR.PATCH, found '$version'"
    exit 1
}

$source = @"
// Generated by tools\write-version.ps1 from version.txt. Do not edit by hand.
namespace SentinelTwo
{
    internal static class AppVersion
    {
        public const string Current = "$version";
    }
}
"@

$target = Join-Path $Root "src\AppVersion.cs"
Set-Content -LiteralPath $target -Value $source -Encoding ASCII
Write-Output "AppVersion.cs written for version $version"
exit 0
